StartupAnalysis:
$ErrorActionPreference='Stop'
Set-Location -LiteralPath 'F:\.codex\worktrees\ecs-relations-worker-3\SomeEngine.Next'
$series='final-startup-r38'
$source='51c8ce75949cf16d7190e14028c655f526d5697b'
$root=[IO.Path]::GetFullPath("artifacts/ecs-relations/measurements/$series")
$evidence=[IO.Path]::GetFullPath("docs/evidence/ECS-Relations-2026-10-19/$series")
New-Item -ItemType Directory -Path $evidence -Force|Out-Null
$submissions=@(Get-Content -LiteralPath (Join-Path $root 'submissions.json') -Raw|ConvertFrom-Json)
function Distribution([double[]]$values){
    [double[]]$sorted=@($values|Sort-Object)
    $n=$sorted.Count
    $medianPosition=($n-1)*0.5
    $p95Position=($n-1)*0.95
    function Percentile([double]$position){
        $lower=[int][Math]::Floor($position)
        $upper=[int][Math]::Ceiling($position)
        $sorted[$lower]+($position-$lower)*($sorted[$upper]-$sorted[$lower])
    }
    [pscustomobject]@{Samples=$n;MedianTicks=(Percentile $medianPosition);P95Ticks=(Percentile $p95Position);MeanTicks=($sorted|Measure-Object -Average).Average;MinTicks=$sorted[0];MaxTicks=$sorted[-1]}
}
$rows=foreach($submission in $submissions){
    $receipt=Get-Content -LiteralPath (Join-Path $submission.QueueDirectory 'result.json') -Raw|ConvertFrom-Json
    if($receipt.ExitCode -ne 0){throw "Startup case failed: $($submission.CaseId)"}
    $samples=@(Get-Content -LiteralPath $submission.Report -Raw|ConvertFrom-Json)
    foreach($sample in $samples){if($sample.SourceCommit -ne $source){throw 'Startup source differs.'}}
    foreach($boundary in @('ProcessToFirstResultTicks','ProcessToExitTicks')){
        $relation=Distribution @($samples|Where-Object Side -eq 'relation'|ForEach-Object{[double]$_.$boundary})
        $handwritten=Distribution @($samples|Where-Object Side -eq 'handwritten'|ForEach-Object{[double]$_.$boundary})
        [pscustomobject]@{CaseId=$submission.CaseId;Boundary=$boundary;SourceCommit=$source;Backend='NativeAOT';Required=$false;StopwatchFrequency=$samples[0].StopwatchFrequency;Relation=$relation;Handwritten=$handwritten;MedianRatio=($relation.MedianTicks/$handwritten.MedianTicks);P95Ratio=($relation.P95Ticks/$handwritten.P95Ticks)}
    }
    Copy-Item -LiteralPath $submission.Report -Destination $evidence -Force
    $queueEvidence=Join-Path $evidence "queues/$($submission.QueueId)"
    New-Item -ItemType Directory -Path $queueEvidence -Force|Out-Null
    foreach($name in @('result.json','stdout.log','stderr.log')){Copy-Item -LiteralPath (Join-Path $submission.QueueDirectory $name) -Destination $queueEvidence -Force}
}
$rows|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $root 'startup-summary.json') -Encoding utf8
$rows|ForEach-Object{
    [pscustomobject]@{CaseId=$_.CaseId;Boundary=$_.Boundary;SourceCommit=$_.SourceCommit;Required=$_.Required;Frequency=$_.StopwatchFrequency;RelationSamples=$_.Relation.Samples;HandwrittenSamples=$_.Handwritten.Samples;RelationMedianTicks=$_.Relation.MedianTicks;HandwrittenMedianTicks=$_.Handwritten.MedianTicks;MedianRatio=$_.MedianRatio;RelationP95Ticks=$_.Relation.P95Ticks;HandwrittenP95Ticks=$_.Handwritten.P95Ticks;P95Ratio=$_.P95Ratio}
}|Export-Csv -LiteralPath (Join-Path $root 'startup-summary.csv') -NoTypeInformation -Encoding utf8
$lines=[Collections.Generic.List[string]]::new()
$lines.Add('# Final same-source process startup')
$lines.Add('')
$lines.Add("Source: $source. NativeAOT, Fixed machine, seven pairs per case with alternating launch order. Each fresh process performs its real first-result query and consumption. These process startup distributions are reported separately from warm-query acceptance.")
$lines.Add('')
$lines.Add('| Case | Boundary | E/H samples | Median E/H ticks | Median ratio | p95 E/H ticks | p95 ratio |')
$lines.Add('| --- | --- | ---: | ---: | ---: | ---: | ---: |')
foreach($row in $rows){$lines.Add("| $($row.CaseId) | $($row.Boundary) | $($row.Relation.Samples)/$($row.Handwritten.Samples) | $($row.Relation.MedianTicks)/$($row.Handwritten.MedianTicks) | $($row.MedianRatio) | $($row.Relation.P95Ticks)/$($row.Handwritten.P95Ticks) | $($row.P95Ratio) |")}
$lines|Set-Content -LiteralPath (Join-Path $root 'report.md') -Encoding utf8
foreach($name in @('submissions.json','queue-submission.json','startup-summary.json','startup-summary.csv','report.md')){Copy-Item -LiteralPath (Join-Path $root $name) -Destination $evidence -Force}
Write-Output ('STARTUP_SUMMARY '+([pscustomobject]@{SourceCommit=$source;Cases=$submissions.Count;Samples=@($submissions).Count*14;Distributions=$rows.Count;Evidence=$evidence}|ConvertTo-Json -Compress))
exit 0

Watcher:
$ErrorActionPreference='Stop'
$taskRoot='F:\.codex\worktrees\ecs-relations-worker-3\SomeEngine.Next'
$control=Join-Path $taskRoot 'artifacts\relations-measurements\final-validation-r38'
New-Item -ItemType Directory -Path $control -Force|Out-Null
$manifestPath=Join-Path $control 'manifest-ready.json'
$masterPath=Join-Path $control 'master-submission.json'
$queueRoot=Join-Path $taskRoot 'artifacts\benchmark-queue'
$watcher=[IO.FileSystemWatcher]::new((Join-Path $taskRoot 'artifacts'),'*.json')
$watcher.IncludeSubdirectories=$true
$watcher.NotifyFilter=[IO.NotifyFilters]::FileName
$watcher.EnableRaisingEvents=$true
$started=[pscustomobject]@{ProcessId=$PID;ProcessStartedAtUtc=(Get-Process -Id $PID).StartTime.ToUniversalTime();WatchReadyAtUtc=[DateTime]::UtcNow}
$started|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $control 'watch-started.json') -Encoding utf8
Write-Output ('WATCH_READY '+($started|ConvertTo-Json -Compress))
try{
    $master=$null
    while(!(Test-Path -LiteralPath $manifestPath) -or !(Test-Path -LiteralPath $masterPath)){
        if(!$master -and (Test-Path -LiteralPath $masterPath)){$master=Get-Content -LiteralPath $masterPath -Raw|ConvertFrom-Json}
        if($master -and (Test-Path -LiteralPath (Join-Path $master.OutputDirectory 'result.json')) -and !(Test-Path -LiteralPath $manifestPath)){
            Write-Output ('MASTER_RECEIPT_BEFORE_MANIFEST '+[DateTime]::UtcNow.ToString('o'))
            exit 2
        }
        $change=$watcher.WaitForChanged([IO.WatcherChangeTypes]::All,50000)
    }
    $initialStarted=[DateTime]::UtcNow
    $manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json
    $master=Get-Content -LiteralPath $masterPath -Raw|ConvertFrom-Json
    $cache=@(foreach($series in $manifest.Series){
        [pscustomobject]@{Series=$series.Series;Submissions=@(Get-Content -LiteralPath $series.Submissions -Raw|ConvertFrom-Json);QueueSubmission=(Get-Content -LiteralPath $series.QueueSubmission -Raw|ConvertFrom-Json)}
    })
    $ids=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $seriesById=[Collections.Generic.Dictionary[string,string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach($series in $cache){foreach($case in $series.Submissions){$id=[string]$case.QueueId;$null=$ids.Add($id);$seriesById.Add($id,[string]$series.Series)}}
    if($ids.Count -ne 139 -or !$ids.SetEquals([string[]]$manifest.CaseQueueIds)){throw 'Cached case IDs differ from the manifest.'}
    $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $finalId=[string]$manifest.AnalysisQueueIds[-1]
    $finalPath=Join-Path $queueRoot ($finalId+'\result.json')
    $ready=[pscustomobject]@{ProcessId=$PID;SourceCommit=$manifest.SourceCommit;InitialObservationStartedAtUtc=$initialStarted;InitialObservationEndedAtUtc=[DateTime]::UtcNow;Series=@($cache.Series);CaseQueueIds=@($manifest.CaseQueueIds);AnalysisQueueIds=@($manifest.AnalysisQueueIds);FinalQueueId=$finalId;FinalReceipt=$finalPath}
    $temporary=Join-Path $control 'watcher-ready.json.tmp'
    [IO.File]::WriteAllText($temporary,($ready|ConvertTo-Json -Depth 6))
    [IO.File]::Move($temporary,(Join-Path $control 'watcher-ready.json'),$true)
    Write-Output ('INITIAL_OBSERVATION_END '+($ready|ConvertTo-Json -Depth 6 -Compress))
    while(!(Test-Path -LiteralPath $finalPath)){
        $change=$watcher.WaitForChanged([IO.WatcherChangeTypes]::All,50000)
        if($change.Name -and [IO.Path]::GetFileName($change.Name) -eq 'result.json'){
            $caseId=[IO.Path]::GetFileName([IO.Path]::GetDirectoryName($change.Name))
            if($ids.Contains($caseId) -and $seen.Add($caseId)){Write-Output ('CASE_RECEIPT '+$seen.Count+'/'+$ids.Count+' '+$seriesById[$caseId]+' '+$caseId+' '+[DateTime]::UtcNow.ToString('o'))}
        }
    }
    $finished=[pscustomobject]@{FinalQueueId=$finalId;ObservedAtUtc=[DateTime]::UtcNow;CaseReceiptsObserved=$seen.Count;CaseCount=$ids.Count}
    $finished|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $control 'final-observed.json') -Encoding utf8
    Write-Output ('FINAL_RECEIPT '+($finished|ConvertTo-Json -Compress))
}
finally{$watcher.Dispose()}

